const response = items[0]?.json ?? {};

const calendarId =
  $('Validate input').first().json.calendar_id;

const calendar =
  response.calendars?.[calendarId] ?? null;

const errors =
  Array.isArray(calendar?.errors)
    ? calendar.errors
    : [];

const providerOk =
  calendar !== null &&
  errors.length === 0;

const firstError =
  errors.length > 0
    ? errors[0]
    : null;

return [
  {
    json: {
      provider_ok: providerOk,
      calendar_id: calendarId,
      busy: Array.isArray(calendar?.busy)
        ? calendar.busy
        : [],
      provider_error_reason:
        firstError?.reason ?? null,
      provider_error_domain:
        firstError?.domain ?? null
    }
  }
];

const input =
  $('Validate input').first().json;

const analyzed =
  $('Analyze free busy').first().json;

const startMs = Date.parse(input.start);
const endMs = Date.parse(input.end);

const durationMs =
  input.duration_minutes * 60_000;

const busyIntervals = analyzed.busy
  .map(interval => ({
    start: Date.parse(interval.start),
    end: Date.parse(interval.end)
  }))
  .filter(interval =>
    Number.isFinite(interval.start) &&
    Number.isFinite(interval.end) &&
    interval.end > interval.start
  )
  .map(interval => ({
    start: Math.max(interval.start, startMs),
    end: Math.min(interval.end, endMs)
  }))
  .filter(interval =>
    interval.end > interval.start
  )
  .sort((a, b) => a.start - b.start);

// Merge overlapping/touching busy intervals
const mergedBusy = [];

for (const interval of busyIntervals) {
  const last = mergedBusy[mergedBusy.length - 1];

  if (!last || interval.start > last.end) {
    mergedBusy.push({ ...interval });
  } else {
    last.end = Math.max(last.end, interval.end);
  }
}

// Find maximal free windows
const freeWindows = [];

let cursor = startMs;

for (const interval of mergedBusy) {
  if (interval.start > cursor) {
    const freeDuration = interval.start - cursor;

    if (freeDuration >= durationMs) {
      freeWindows.push({
        start: new Date(cursor).toISOString(),
        end: new Date(interval.start).toISOString(),
        duration_minutes: Math.floor(
          freeDuration / 60_000
        )
      });
    }
  }

  cursor = Math.max(cursor, interval.end);
}

if (cursor < endMs) {
  const freeDuration = endMs - cursor;

  if (freeDuration >= durationMs) {
    freeWindows.push({
      start: new Date(cursor).toISOString(),
      end: new Date(endMs).toISOString(),
      duration_minutes: Math.floor(
        freeDuration / 60_000
      )
    });
  }
}

return [
  {
    json: {
      success: true,
      data: freeWindows,
      meta: {
        tool: 'find_free_time',
        count: freeWindows.length,
        calendar_id: input.calendar_id,
        requested_duration_minutes:
          input.duration_minutes
      }
    }
  }
];

const j = items[0]?.json ?? {};

const httpCode = Number(
  j?.details?.httpCode ??
  j?.statusCode ??
  j?.error?.statusCode ??
  0
);

const reason =
  typeof j.provider_error_reason === 'string'
    ? j.provider_error_reason
    : '';

const isNotFound =
  httpCode === 404 ||
  reason === 'notFound';

return [
  {
    json: {
      success: false,
      error: {
        code: isNotFound
          ? 'NOT_FOUND'
          : 'UPSTREAM_ERROR',
        message: isNotFound
          ? 'Google Calendar not found'
          : 'Google Calendar FreeBusy request failed'
      },
      meta: {
        tool: 'find_free_time',
        count: 0
      }
    }
  }
];
